/** Two concave physical halves retain the original rounded outer plate and window.
 * A mating seam is explicit: the public API has no arbitrary polygon-with-hole extrusion. */
export function createPlate(k){const split=48.7,arc=(out,x,y,r,a,b)=>{for(let i=1;i<=8;i++){const t=(a+(b-a)*i/8)*Math.PI/180;out.push([x+r*Math.cos(t),y+r*Math.sin(t)]);}},left=(edge)=>{const p=[[edge+6,-68],[split,-68],[split,35.6],[44.6,35.6]];arc(p,44.6,37.8,2.2,270,180);p.push([42.4,43.8]);arc(p,44.6,43.8,2.2,180,90);p.push([split,46],[split,68],[edge+6,68]);arc(p,edge+6,62,6,90,180);p.push([edge,-62]);arc(p,edge+6,-62,6,180,270);return p;};return [k.extrude('plate.left',{plan:left(-72),height:2}),k.extrude('plate.right',{plan:left(2*split-72).map(([x,y])=>[2*split-x,y]).reverse(),height:2})];}
